addEventListener('keyup',e=>{if(keyMap[e.code]){e.preventDefault();input[keyMap[e.code]]=false}});
addEventListener('blur',()=>Object.keys(input).forEach(k=>input[k]=false));
document.querySelectorAll('[data-control]').forEach(btn=>{const k=btn.dataset.control;const down=e=>{e.preventDefault();input[k]=true;btn.classList.add('active');btn.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();input[k]=false;btn.classList.remove('active')};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});
