function approachStop(){const stop=stops[activeStop];if(!stop)return;const distance=stop.z-bus.position.z;
 if(Math.abs(distance)<6.5&&speed<.65&&Math.abs(bus.position.x)<3){if(stopped!==activeStop+1){stopped=activeStop+1;speed=0;bus.position.z=stop.z;toast(`${stop.name}: Fahrgäste steigen ein`);titleEl.textContent='Fahrgäste steigen ein';subEl.textContent='Einen Moment Geduld – gleich geht es weiter.';setTimeout(()=>{if(activeStop===stopped-1){activeStop++;updateHUD();toast('Alle an Bord – weiter geht’s!')}},2100)}}else if(distance < -12){toast(`Haltestelle ${stop.name} verpasst – nächste bitte!`);activeStop++;updateHUD()}}
function finish(){finished=true;playing=false;document.querySelector('#finish').classList.add('show')}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.045,(now-last)/1000);last=now;
 if(playing&&!paused&&!finished){const acceleration=9.8,braking=17; if(input.gas)speed+=acceleration*dt;else speed-=2.2*dt;if(input.brake)speed-=braking*dt;speed=THREE.MathUtils.clamp(speed,0,14.2);
  const steer=(input.right?1:0)-(input.left?1:0);bus.position.x+=steer*(1.55+speed*.19)*dt;bus.position.x=THREE.MathUtils.clamp(bus.position.x,-5.7,5.7);if(Math.abs(bus.position.x)>4.4){speed=Math.min(speed,5.2)}
  bus.position.z+=speed*dt;bus.rotation.y=THREE.MathUtils.damp(bus.rotation.y,-steer*.065,.7,dt);bus.position.y=Math.sin(now*.012)*.018*(speed/14);if(activeStop<stops.length)approachStop();else if(bus.position.z>330)finish();
  if(Math.floor(now/220)!==Math.floor((now-dt*1000)/220))updateHUD();
 }
 const target=new THREE.Vector3(bus.position.x*.62,1.25,bus.position.z+7);const desired=new THREE.Vector3(bus.position.x*.72,5.5,bus.position.z-10.5);camera.position.lerp(desired,1-Math.exp(-dt*2.7));camera.lookAt(target);
 stopZones.forEach((s,i)=>{const a=i===activeStop?(.72+Math.sin(now*.005)*.2):.28;s.ring.material.opacity=a;s.halo.material.opacity=i===activeStop?.10+Math.sin(now*.005)*.035:.035});renderer.render(scene,camera)}
requestAnimationFrame(animate);updateHUD();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
